"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["80834"],{69796(e){e.exports=JSON.parse('{"id":"FIN-010","slug":"net-income-personal","term":"Net Income (Personal)","also_known_as":["Take-Home Pay"],"difficulty":"Beginner","definition":"Net income, for a person, is the money left from your earnings after income tax and other deductions have been taken out. It is often called take-home pay.","explanation":["Net income is what arrives in your bank account. It is calculated by starting with gross income and subtracting deductions such as income tax, social security or national insurance contributions, and any pension contributions or other amounts taken directly from pay.","For example, a person with a gross salary of 4,500 a month might have 750 deducted for income tax, 300 for social security and 225 for a workplace pension. Their net income is 3,225.","Net income is the right figure to use for budgeting, because it is the money you can actually spend or save. Planning a budget from gross income is a common mistake that leads to overspending.","The term also has a separate meaning in business. In accounting, net income is a company\'s profit after all expenses, interest and taxes, often called the bottom line. That meaning is covered in its own entry under Accounting & Financial Statements."],"note":"","total":1500,"prev":{"slug":"net-income-accounting","term":"Net Income (Accounting)"},"next":{"slug":"net-interest-income","term":"Net Interest Income"}}')}}]);